css:
.list {
  display: grid;
  grid-template-columns: 120px 1fr 120px;
  gap: 10px 12px;
  padding: 12px;
  max-width: 480px;
}

.key {
  font-weight: 600;
}

.edit {
  justify-self: end; /* right edge of the column */
  padding: 4px 12px;
  border: 0;
  border-radius: 4px;
  background: #3f3f46;
  color: #fafafa;
}
